package com.esn.smp.gameplay;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import java.io.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
public final class HomesWarps implements CommandExecutor{
 private final JavaPlugin plugin;private final File file;private final YamlConfiguration y;public HomesWarps(JavaPlugin p){plugin=p;file=new File(p.getDataFolder(),"locations.yml");y=YamlConfiguration.loadConfiguration(file);}
 private void save(){try{y.save(file);}catch(IOException e){plugin.getLogger().severe("Location save failed: "+e.getMessage());}}
 private String home(UUID u,String n){return "homes."+u+"."+n.toLowerCase();}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;String n=c.getName().toLowerCase();if(n.equals("sethome")){String h=a.length>0?a[0]:"home";y.set(home(p.getUniqueId(),h),p.getLocation());save();p.sendMessage(ChatColor.GREEN+"Home '"+h+"' set.");return true;}if(n.equals("home")){String h=a.length>0?a[0]:"home";Location x=y.getLocation(home(p.getUniqueId(),h));if(x==null)p.sendMessage(ChatColor.RED+"Home not found.");else p.teleport(x);return true;}if(n.equals("delhome")){String h=a.length>0?a[0]:"home";y.set(home(p.getUniqueId(),h),null);save();p.sendMessage(ChatColor.YELLOW+"Home removed.");return true;}if(n.equals("homes")){var sec=y.getConfigurationSection("homes."+p.getUniqueId());p.sendMessage(ChatColor.GOLD+"Homes: "+(sec==null?"none":String.join(", ",sec.getKeys(false))));return true;}if(n.equals("setwarp")){if(a.length<1)return false;y.set("warps."+a[0].toLowerCase(),p.getLocation());save();p.sendMessage(ChatColor.GREEN+"Warp set.");return true;}if(n.equals("delwarp")){if(a.length<1)return false;y.set("warps."+a[0].toLowerCase(),null);save();p.sendMessage(ChatColor.YELLOW+"Warp removed.");return true;}if(n.equals("warp")){if(a.length<1)return false;Location x=y.getLocation("warps."+a[0].toLowerCase());if(x==null)p.sendMessage(ChatColor.RED+"Warp not found.");else p.teleport(x);return true;}if(n.equals("warps")){var sec=y.getConfigurationSection("warps");p.sendMessage(ChatColor.GOLD+"Warps: "+(sec==null?"none":String.join(", ",sec.getKeys(false))));return true;}if(n.equals("rtp")){World w=p.getWorld();int radius=5000;for(int tries=0;tries<12;tries++){int x=ThreadLocalRandom.current().nextInt(-radius,radius+1),z=ThreadLocalRandom.current().nextInt(-radius,radius+1);int yy=w.getHighestBlockYAt(x,z)+1;Location d=new Location(w,x+.5,yy,z+.5);Material below=w.getBlockAt(x,yy-1,z).getType();if(!below.isAir()&&!below.equals(Material.LAVA)&&!below.equals(Material.WATER)){p.teleport(d);p.sendMessage(ChatColor.GREEN+"Randomly teleported.");return true;}}p.sendMessage(ChatColor.RED+"Could not find a safe RTP location. Try again.");return true;}return true;}
}